import { TranslationKey } from './en';
import { Message } from './language';

/**
 * The Arabic the console says, in Modern Standard Arabic as Jordanian business software writes it.
 *
 * Typed as a complete `Record<TranslationKey, …>`, so this file cannot fall behind `en.ts`: a key
 * added there and not here fails the build rather than showing an English sentence to an Arabic
 * reader, which is the failure mode nobody notices until a customer does.
 *
 * Two habits worth keeping when adding to it:
 *
 * - A dealership is a "مكتب" — or "مكتب التأجير" where "مكتب" alone would be ambiguous — and a
 *   vehicle is a "سيارة". The owner decided on 2026-09-13 that the console speaks the Customer
 *   App's vocabulary (Khadra.Mobile/lib/l10n/app_ar.arb), so a customer and the office they rent
 *   from use the same words for the same things; `dictionaries.spec.ts` fails if the gallery and
 *   vehicle words the console used before come back. The brand in Arabic prose is "خضرا", and the
 *   platform's own operators are "مشرفون". "تاجر", the literal reading of Dealer, is still wrong:
 *   it would mean a merchant of any kind.
 * - Plural entries carry all six Arabic categories. `Intl.PluralRules` picks between them; leaving
 *   one out silently falls back to `other`, which is grammatical only by accident.
 */
